<?php $title = 'Manage users'; ?>
<section class="mx-auto max-w-6xl px-5 py-12"><div class="mb-8"><p class="eyebrow">ACCOUNT MANAGEMENT</p><h1 class="mt-2 font-display text-4xl font-extrabold">Users.</h1><p class="mt-2 text-sm text-slate-500">Change account roles or suspend access. Accounts are retained with booking history.</p></div><form class="mb-5 flex gap-2" method="get" action="<?= h(url('admin.users')) ?>"><input class="control flex-1" name="search" value="<?= h($search) ?>" placeholder="Search name or email"><button class="primary-button !mt-0">Search</button><a class="self-center text-xs underline" href="<?= h(url('admin.users')) ?>">Clear</a></form><div class="overflow-x-auto border border-stone-200 bg-white"><table class="w-full min-w-[700px] text-left text-sm"><thead class="bg-stone-100 text-xs"><tr><th class="p-4">NAME</th><th class="p-4">EMAIL</th><th class="p-4">ROLE</th><th class="p-4">ACCESS</th><th class="p-4">SAVE</th></tr></thead><tbody><?php foreach ($users as $item): ?><tr class="border-t border-stone-100"><td class="p-4 font-semibold"><?= h($item['name']) ?></td><td class="p-4"><?= h($item['email']) ?></td><td colspan="3" class="p-4"><form class="flex flex-wrap items-center gap-3" method="post" action="<?= h(url('admin.user.update')) ?>"><?= csrf_field() ?><input type="hidden" name="user_id" value="<?= (int)$item['id'] ?>"><select class="control" name="role"><option value="customer" <?= $item['role']==='customer'?'selected':'' ?>>Customer</option><option value="admin" <?= $item['role']==='admin'?'selected':'' ?>>Admin</option></select><label class="flex items-center gap-2 text-xs"><input type="checkbox" name="is_active" value="1" <?= (int)$item['is_active']?'checked':'' ?>> Active</label><button class="rounded bg-slate-900 px-3 py-2 text-xs font-bold text-white">Save</button><span class="text-xs text-slate-400">Joined <?= h(date('M j, Y',strtotime($item['created_at']))) ?></span></form></td></tr><?php endforeach; ?><?php if (!$users): ?><tr><td colspan="5" class="p-10 text-center text-slate-500">No accounts found.</td></tr><?php endif; ?></tbody></table></div></section>
